import json, re, sys
from http.server import BaseHTTPRequestHandler, HTTPServer
from pathlib import Path

HERE = Path(__file__).parent
ROUTES = [("GET", r"^/pets$", 200, "listPets"), ("GET", r"^/pets/[^/]+$", 200, "getPet"),
          ("DELETE", r"^/pets/[^/]+$", 204, None)]


class Mock(BaseHTTPRequestHandler):
    def answer(self, method):
        for m, rx, status, op in ROUTES:
            if m == method and re.match(rx, self.path):
                body = (HERE / "fixtures" / f"{op}.json").read_text() if op else "{}"
                self.send_response(status); self.send_header("Content-Type", "application/json"); self.end_headers()
                self.wfile.write(body.encode()); return
        self.send_response(404); self.end_headers()

    def do_GET(self): self.answer("GET")
    def do_DELETE(self): self.answer("DELETE")


HTTPServer(("127.0.0.1", int(sys.argv[1]) if len(sys.argv) > 1 else 4010), Mock).serve_forever()

